/* ── 단어 창 안에 바로 놓인 쓰기 칸 — 누를 것 없이 곧장 그으면 된다 ── */
.wk-wrap{margin-top:14px;padding-top:13px;border-top:1px solid var(--line)}
.wk-hd{display:flex;align-items:baseline;gap:7px;margin-bottom:8px}
.wk-hd .ttl{flex:1;font-size:12.5px;color:var(--sub);text-align:left;line-height:1.3}

/* ── 단어 창 안에 바로 놓인 쓰기 칸 — 누를 것 없이 곧장 그으면 된다 ── */
.wk-wrap{margin:0 0 16px;padding-bottom:14px;border-bottom:1px solid var(--line)}
.wk-hd{display:flex;align-items:baseline;gap:7px;margin-bottom:8px;padding-right:38px}
.wk-hd .ttl{flex:1;font-size:12.5px;color:var(--sub);text-align:left;line-height:1.3}
